export type KolSource = 'axiom' | 'fomo' | 'fomo-trading' | 'gmgn' | 'manual';

export const KOL_RANKING_SOURCES = ['gmgn', 'manual', 'axiom', 'fomo'] as const;

export type KolPeriodStats = {
  realizedPnlUsd: number | null;
  pnlPercent: number | null;
  trades: number | null;
};

export type NormalizedKolSourceRow = {
  source: KolSource;
  chain: Chain;
  address: string;
  family: 'solana' | 'evm';
  identity: {
    provider: 'x' | 'fomo';
    externalId: string;
    display: string;
  };
  slugBase: string;
  displayName: string;
  avatarUrl: string | null;
  sourceRank: number | null;
  stats: Partial<Record<KolRankingPeriod, KolPeriodStats>>;
};

const KOL_RANKING_PERIODS: KolRankingPeriod[] = ['1d', '7d', '30d'];

function parseAliasedText(
  row: Record<string, unknown>,
  primaryField: string,
  aliasField: string,
): { valid: boolean; value: string | null } {
  const primary = normalizeNonEmptyString(row[primaryField]);
  const alias = normalizeNonEmptyString(row[aliasField]);
  if (primary && alias && primary.toLowerCase() !== alias.toLowerCase()) {
    return { valid: false, value: null };
  }
  return { valid: true, value: primary || alias };
}

export function parseAvatarUrl(value: unknown): string | null {
  const candidate = normalizeNonEmptyString(value);
  if (!candidate) {
    return null;
  }
  try {
    const url = new URL(candidate);
    return url.protocol === 'https:' ? url.toString() : null;
  } catch {
    return null;
  }
}

function getPeriodValue(
  row: Record<string, unknown>,
  name: 'realized_profit' | 'pnl' | 'txs',
  period: KolRankingPeriod,
): number | null {
  return parseFiniteNumberValue(row[`${name}_${period}`]);
}

export function normalizeKolSourceRow(
  value: unknown,
  source: KolSource,
  configuredChain: Chain,
  period: KolRankingPeriod | null,
  rowIndex: number,
): NormalizedKolSourceRow | null {
  const row = getObjectValue(value);
  if (!row) {
    return null;
  }
  const chainField = parseAliasedText(row, 'chain', 'network');
  if (!chainField.valid) {
    return null;
  }
  const explicitChain = chainField.value;
  const chain = explicitChain ? normalizeChain(explicitChain) : configuredChain;
  if (!chain || chain !== configuredChain) {
    return null;
  }

  const addressField = parseAliasedText(row, 'address', 'wallet_address');
  if (!addressField.valid) {
    return null;
  }
  const rawAddress = addressField.value;
  if (!rawAddress || !isAddressForChain(chain, rawAddress)) {
    return null;
  }
  const address = normalizeAddressForChain(chain, rawAddress);

  const rawUsername = row.twitter_username;
  const xUsername = normalizeXUsername(rawUsername);
  const xDisplay = formatXUsername(rawUsername);
  if (!xUsername || !xDisplay) {
    return null;
  }
  const sourceName = normalizeNonEmptyString(row.twitter_name);
  const displayName = sourceName ?? xDisplay;
  const explicitRank = parseFiniteNumberValue(row.rank);
  const stats = period
    ? Object.fromEntries(
        KOL_RANKING_PERIODS.map((rankingPeriod) => {
          const pnlRatio = getPeriodValue(row, 'pnl', rankingPeriod);
          return [
            rankingPeriod,
            {
              realizedPnlUsd: getPeriodValue(row, 'realized_profit', rankingPeriod),
              pnlPercent: pnlRatio === null ? null : pnlRatio * 100,
              trades: getPeriodValue(row, 'txs', rankingPeriod),
            },
          ];
        }),
      )
    : {};

  return {
    source,
    chain,
    address,
    family: getWalletFamilyForChain(chain),
    identity: { provider: 'x', externalId: xUsername, display: xDisplay },
    slugBase: xUsername,
    displayName,
    avatarUrl: parseAvatarUrl(row.avatar),
    sourceRank:
      explicitRank !== null && Number.isInteger(explicitRank)
        ? explicitRank
        : rowIndex + 1,
    stats,
  };
}

export function normalizeAxiomStatsRow(
  directoryRow: unknown,
  response: unknown,
  period: KolRankingPeriod,
  rowIndex: number,
): NormalizedKolSourceRow | null {
  const normalized = normalizeKolSourceRow(
    directoryRow,
    'axiom',
    'solana',
    null,
    rowIndex,
  );
  const envelope = getObjectValue(response);
  const stats = envelope ? getObjectValue(envelope.data) : null;
  if (!normalized || !stats || normalizeNonEmptyString(stats.period) !== period) {
    return null;
  }

  const buy = parseFiniteNumberValue(stats.buy);
  const sell = parseFiniteNumberValue(stats.sell);
  if (buy === null || sell === null || buy < 0 || sell < 0) {
    return null;
  }
  const trades = buy + sell;
  normalized.sourceRank = null;
  if (trades === 0) {
    return normalized;
  }

  const realizedPnlUsd = parseFiniteNumberValue(stats.realized_profit);
  const pnlRatio = parseFiniteNumberValue(stats.realized_profit_pnl);
  if (realizedPnlUsd === null || pnlRatio === null) {
    return null;
  }
  normalized.stats[period] = {
    realizedPnlUsd,
    pnlPercent: pnlRatio * 100,
    trades,
  };
  return normalized;
}

