export type KolSnapshotSelectionRow = {
  wallet_id: string;
  chain: Chain;
  source: string;
  expires_at: number;
};

export type KolSyncStatusRow = {
  source: string;
  chain: Chain | 'all';
  status: 'running' | 'succeeded' | 'failed';
};

const SOURCE_PRIORITY: Record<string, number> = {
  gmgn: 3,
  manual: 4,
  axiom: 2,
  fomo: 1,
};

export const KOL_RANKING_SOURCE_SQL = KOL_RANKING_SOURCES.map(
  (source) => `'${source}'`,
).join(', ');

export function buildCurrentKolSnapshotSql(
  snapshotAlias: string,
  nowExpression: string,
): string {
  return `${snapshotAlias}.source IN (${KOL_RANKING_SOURCE_SQL})
    AND ${snapshotAlias}.period IN ('1d', '7d', '30d')
    AND (
      ${snapshotAlias}.expires_at > ${nowExpression}
      OR COALESCE(
        (
          SELECT r.status FROM kol_sync_runs r
           WHERE r.source = ${snapshotAlias}.source
             AND r.chain = ${snapshotAlias}.chain
             AND r.period = ${snapshotAlias}.period
           ORDER BY r.started_at DESC, r.run_id DESC
           LIMIT 1
        ),
        (
          SELECT r.status FROM kol_sync_runs r
           WHERE r.source = ${snapshotAlias}.source
             AND r.chain = 'all'
             AND r.period = ${snapshotAlias}.period
           ORDER BY r.started_at DESC, r.run_id DESC
           LIMIT 1
        )
      ) IN ('running', 'failed')
    )`;
}

export function selectKolSnapshots<Row extends KolSnapshotSelectionRow>(
  rows: Row[],
  syncRows: KolSyncStatusRow[],
  now = Date.now(),
): Row[] {
  const latestStatus = new Map(
    syncRows.map((row) => [`${row.source}:${row.chain}`, row.status]),
  );
  const chosenByWalletChain = new Map<string, Row>();
  for (const row of rows) {
    const fresh = row.expires_at > now;
    const latest =
      latestStatus.get(`${row.source}:${row.chain}`) ??
      latestStatus.get(`${row.source}:all`);
    if (!fresh && latest !== 'running' && latest !== 'failed') {
      continue;
    }
    const key = `${row.wallet_id}:${row.chain}`;
    const existing = chosenByWalletChain.get(key);
    if (
      !existing ||
      (SOURCE_PRIORITY[row.source] ?? 0) > (SOURCE_PRIORITY[existing.source] ?? 0)
    ) {
      chosenByWalletChain.set(key, row);
    }
  }
  return Array.from(chosenByWalletChain.values());
}

export type LatestKolSyncStatusRow = KolSyncStatusRow & {
  period: KolRankingPeriod;
  started_at: number;
};

export function getLatestKolSyncStatuses(
  db: D1Database,
  periods: KolRankingPeriod[],
  chain: Chain | 'all',
): Promise<LatestKolSyncStatusRow[]> {
  const chainIndex = periods.length + 1;
  return getAllRows<LatestKolSyncStatusRow>(
    db
      .prepare(
        `SELECT source, chain, period, status, started_at
           FROM (
             SELECT source, chain, period, status, started_at,
                    ROW_NUMBER() OVER (
                      PARTITION BY source, chain, period
                      ORDER BY started_at DESC, run_id DESC
                    ) AS row_number
               FROM kol_sync_runs
              WHERE source IN (${KOL_RANKING_SOURCE_SQL})
                AND period IN (${buildIndexedPlaceholders(periods.length)})
                AND (
                  ?${chainIndex} = 'all'
                  OR chain = ?${chainIndex}
                  OR chain = 'all'
                )
           )
          WHERE row_number = 1
          ORDER BY source, chain, period`,
      )
      .bind(...periods, chain),
  );
}
export function buildFomoRankSnapshotStatement(
  db: D1Database,
  profileId: string,
  period: Exclude<FomoPeriod, 'all'>,
  row: unknown,
  rank: number,
  observedAt: number,
  externalId?: string,
): D1PreparedStatement {
  const user = getObjectValue(row) ?? {};
  const pnlField = {
    '1d': 'pnl24h',
    '7d': 'pnl7d',
    '30d': 'pnl30d',
  }[period];
  return db
    .prepare(
      `INSERT INTO kol_wallet_rank_snapshots (
         wallet_id, chain, period, source, source_rank, realized_pnl_usd,
         pnl_percent, trade_count, observed_at, expires_at
       )
       SELECT ranked.wallet_id, ranked.chain, ?2, 'fomo', ?3, ?4, NULL, ?5, ?6, ?7
         FROM (
           SELECT w.wallet_id, c.chain
             FROM profile_wallets w
             JOIN profile_wallet_chains c ON c.wallet_id = w.wallet_id
            WHERE w.profile_id = ?1
              ${
                externalId
                  ? `AND EXISTS (
                SELECT 1 FROM profile_external_identities i
                 WHERE i.provider = 'fomo' AND i.external_id = ?8 COLLATE NOCASE
                   AND i.profile_id = ?1
              )`
                  : ''
              }
              AND w.status = 'active'
              AND c.status = 'active'
              AND c.source = 'fomo-trading'
              AND c.chain IN ('solana', 'robinhood')
            ORDER BY CASE c.chain WHEN 'solana' THEN 0 ELSE 1 END, w.wallet_id
            LIMIT 1
         ) ranked
        WHERE true
       ON CONFLICT(wallet_id, chain, period, source) DO UPDATE SET
         source_rank = excluded.source_rank,
         realized_pnl_usd = excluded.realized_pnl_usd,
         pnl_percent = NULL,
         trade_count = excluded.trade_count,
         observed_at = excluded.observed_at,
         expires_at = excluded.expires_at`,
    )
    .bind(
      profileId,
      period,
      rank,
      parseFiniteNumberValue(user[pnlField]),
      parseFiniteNumberValue(user.numTrades),
      observedAt,
      observedAt + FOMO_RANK_FRESH_MS,
      ...(externalId ? [externalId] : []),
    );
}

const MAX_PAGES_PER_TOKEN = 3;

async function syncFomoUsers(
  db: D1Database,
  env: Env,
  { scheduledAt, deadline, signal }: JobRunContext,
): Promise<FomoUserSyncResult> {
  const scheduledDay = Math.floor(scheduledAt / DAY_MS) * DAY_MS;

  const fetchFomo = async (operation: () => Promise<unknown>): Promise<unknown> => {
    signal.throwIfAborted();
    return await operation();
  };

  const runLeaderboard = async (
    period: (typeof LEADERBOARD_PERIODS)[number],
  ): Promise<FomoSliceResult> => {
    const rawById = new Map<string, unknown>();
    const rankedUsers = new Set<string>();
    const observedAt = Date.now();
    return await reconcileRows(
      db,
      'fomo',
      'all',
      period,
      scheduledDay,
      async () => {
        const payload = getObjectValue(
          await fetchFomo(() => fetchFomoLeaderboard(env, period)),
        );
        const leaderboard = getObjectValue(payload?.responseObject)?.leaderboard;
        return requireArray(leaderboard, 'leaderboard');
      },
      {
        signal,
        normalizeRows: async (rows) => {
          for (const row of rows) {
            const id = getUserId(row);
            if (id) {
              rawById.set(id.toLowerCase(), row);
            }
          }
          return await normalizeFomoUserRows(rows, 'fomo');
        },
        buildExtraWrites: (row, profileId) => {
          const externalId = row.identity.externalId.toLowerCase();
          if (period === 'all') {
            return [];
          }
          const rankKey = `${profileId}:${externalId}`;
          if (rankedUsers.has(rankKey)) {
            return [];
          }
          const raw = rawById.get(externalId);
          if (!raw || row.sourceRank === null) {
            return [];
          }
          rankedUsers.add(rankKey);
          return [
            buildFomoRankSnapshotStatement(
              db,
              profileId,
              period,
              raw,
              row.sourceRank,
              observedAt,
              row.identity.externalId,
            ),
          ];
        },
      },
    );
